// AddGlobalFields adds fields to every subsequent log entry.
func AddGlobalFields(fields ...LogField) {
	fieldMu.Lock()
	globalFields = append(globalFields, fields...)
	fieldMu.Unlock()
}

if len(c.ServiceName) > 0 {
			AddGlobalFields(Field("serviceName", c.ServiceName))
		}

func output(writer io.Writer, level string, val interface{}, fields ...LogField) {
	fieldMu.RLock()
	allFields := make([]LogField, 0, len(globalFields)+len(fields))
	allFields = append(allFields, globalFields...)
	fieldMu.RUnlock()
	fields = append(allFields, fields...)

	switch atomic.LoadUint32(&encoding) {
	case plainEncodingType:
		writePlainAny(writer, level, val, buildFields(fields...)...)
	default:
		entry := make(logEntry)
		for _, field := range fields {
			entry[field.Key] = field.Value
		}
		entry[timestampKey] = getTimestamp()
		entry[levelKey] = level
		entry[contentKey] = val
		writeJson(writer, entry)
	}
}

