func TestGlobalFields(t *testing.T) {
	oldWriter := writer.Swap(nil)
	oldEncoding := atomic.LoadUint32(&encoding)
	oldLevel := atomic.LoadUint32(&logLevel)
	fieldMu.Lock()
	oldFields := append([]LogField(nil), globalFields...)
	globalFields = nil
	fieldMu.Unlock()
	defer func() {
		writer.Store(oldWriter)
		atomic.StoreUint32(&encoding, oldEncoding)
		atomic.StoreUint32(&logLevel, oldLevel)
		fieldMu.Lock()
		globalFields = oldFields
		fieldMu.Unlock()
	}()

	AddGlobalFields(Field("global", "first"))
	AddGlobalFields(Field("region", "west"))
	SetLevel(InfoLevel)

	for _, test := range []struct {
		name     string
		encoding uint32
	}{
		{name: "json", encoding: jsonEncodingType},
		{name: "plain", encoding: plainEncodingType},
	} {
		t.Run(test.name, func(t *testing.T) {
			var buf bytes.Buffer
			atomic.StoreUint32(&encoding, test.encoding)
			SetWriter(NewWriter(&buf))
			Infow("message", Field("requestId", "req-1"))

			if test.encoding == jsonEncodingType {
				var entry map[string]interface{}
				assert.NoError(t, json.Unmarshal(bytes.TrimSpace(buf.Bytes()), &entry))
				assert.Equal(t, "message", entry[contentKey])
				assert.Equal(t, "first", entry["global"])
				assert.Equal(t, "west", entry["region"])
				assert.Equal(t, "req-1", entry["requestId"])
			} else {
				assert.Contains(t, buf.String(), "message")
				assert.Contains(t, buf.String(), "global=first")
				assert.Contains(t, buf.String(), "region=west")
				assert.Contains(t, buf.String(), "requestId=req-1")
			}
		})
	}
}

